						<div class="slide_list swiper-slide preview_resize swiper-slide-duplicate swiper-slide-duplicate-active" data-swiper-slide-index="0" role="group" aria-label="1 / 9" style="width: 420px;">
								<img src="https://cdn.salondeletter.com/forever/202605/29/5/6ae16869.png" alt="" style="max-height: 100%;">
							</div></div>
						<div class="swiper-button-next" tabindex="0" role="button" aria-label="Next slide" aria-controls="swiper-wrapper-1a4dafcf315804210"></div>
